export const BERX_WORLD_WGSL = "// The BERX forward pass, in WGSL. This file is the only copy of it.\n//\n// Two backends run this exact text: @berx/spatial-web's WebGPU renderer,\n// which imports it through @berx/spatial-shaders, and the native\n// berx-spatial-native crate, which include_str!s it. A shader duplicated\n// per backend is how two renderers quietly stop drawing the same world.\n//\n// The same microfacet BRDF the WebGL2 backend runs: GGX, height-correlated\n// Smith visibility, Schlick Fresnel, metalness splitting the diffuse and\n// specular lobes, one directional key, up to four windowed point lights, and\n// and image-based lighting from an ANALYTIC environment — a closed-form\n// room rather than a captured cubemap, because BERX ships no HDR asset and\n// a closed form is the only thing four languages can evaluate identically.\n// There is no post chain here, and both backends' reported capabilities say\n// so.\n//\n// The key light casts. Its camera is fitted in the shared core\n// (@berx/spatial's berxShadowCamera) so every backend puts the light in\n// exactly the same place, and this file only reads the depth it captured:\n// 3x3 PCF, a normal-offset sample, and a shadow that removes the KEY term\n// only. Ambient and the point lights are untouched, because a surface in\n// shadow still receives the bounced room — zeroing the pixel is what makes\n// a render look like a cutout rather than a place.\n//\n// One thing differs from the GLSL source, and it is a clip-space convention\n// rather than shading: WGSL depth runs 0..1 where GL runs -1..1, so the host\n// hands this shader a projection already remapped.\n//\n// Media is a planar projection onto the face that points at you, exactly as\n// in the GLSL pass: object-space position and normal give the UVs from the\n// local XY extent, and the texture is applied only where the surface faces\n// +Z, so an avatar on an orb reads as a face rather than as a photograph\n// smeared around a ball. A backend with no image to bind binds a 1x1 texture\n// and leaves the flag at zero; nothing is approximated with a colour.\n\nstruct Globals {\n  proj: mat4x4<f32>,\n  view: mat4x4<f32>,\n  camera: vec4<f32>,\n  ambient: vec4<f32>,\n  key_dir: vec4<f32>,\n  key_col: vec4<f32>,   // rgb, intensity in w\n  // The light's own view-projection, already in this API's depth range.\n  light_vp: mat4x4<f32>,\n  // x = 1/mapSize, y = depth bias, z = normal bias, w = strength (0 = off)\n  shadow: vec4<f32>,\n  // THE ROOM, packed by the shared core's berxEnvironmentUniform. The\n  // order is that function's, not this file's: changing it here without\n  // changing it there is how a renderer ends up lit by the ground\n  // colour. w components carry the scalars so the block stays five\n  // vec4s rather than five vec4s and four loose floats.\n  env_zenith: vec4<f32>,   // rgb zenith,          w = sun intensity\n  env_horizon: vec4<f32>,  // rgb horizon,         w = sun sharpness\n  env_ground: vec4<f32>,   // rgb ground * bounce, w = overall intensity\n  env_sun_dir: vec4<f32>,  // xyz toward the key light\n  env_sun: vec4<f32>,      // rgb sun colour\n  // x = 1 when an SSAO pass ran for this frame, 0 when it did not.\n  ssao: vec4<f32>,\n};\n\nstruct Draw {\n  model: mat4x4<f32>,\n  base: vec4<f32>,              // rgb base colour, w = local half-extent in X\n  emissive: vec4<f32>,          // rgb emission,    w = local half-extent in Y\n  surface: vec4<f32>,           // metalness, roughness, opacity, transmission\n  pl_pos: array<vec4<f32>, 4>,  // xyz position, w range\n  pl_col: array<vec4<f32>, 4>,  // rgb colour, w intensity\n  // x = point light count, yz = UV cover/contain correction, w = has texture\n  counts: vec4<f32>,\n};\n\n@group(0) @binding(0) var<uniform> g: Globals;\n// A comparison sampler, not a plain one: the hardware does the depth test\n// per sample and averages the RESULTS, which is what makes a 3x3 tap a soft\n// edge instead of four hard ones. Sampling depth and comparing afterwards\n// would average DEPTHS, and an averaged depth is a surface that exists\n// nowhere.\n@group(0) @binding(1) var shadow_sampler: sampler_comparison;\n@group(0) @binding(2) var shadow_texture: texture_depth_2d;\n// The occlusion the SSAO pass computed for this frame, at screen\n// resolution. Read with textureLoad rather than sampled: it is looked up\n// at exactly the fragment's own pixel, so there is nothing to filter and\n// no sampler to keep in step across three backends. A backend with the\n// pass switched off binds a 1x1 white texture and ssao_on stays 0.\n@group(0) @binding(3) var ao_texture: texture_2d<f32>;\n@group(1) @binding(0) var<uniform> d: Draw;\n@group(2) @binding(0) var media_sampler: sampler;\n@group(2) @binding(1) var media_texture: texture_2d<f32>;\n\nstruct VsOut {\n  @builtin(position) clip: vec4<f32>,\n  @location(0) n: vec3<f32>,\n  @location(1) w: vec3<f32>,\n  // object space, so media projects onto the form rather than the screen\n  @location(2) local: vec3<f32>,\n  @location(3) local_n: vec3<f32>,\n};\n\n/**\n * The depth-only pass, from the light.\n *\n * The same vertex data and the same model matrix as the main pass — a\n * shadow cast by a different shape from the one drawn is worse than no\n * shadow, because it is a shape that is not there.\n */\n@vertex\nfn vs_shadow(@location(0) p: vec3<f32>, @location(1) n: vec3<f32>) -> @builtin(position) vec4<f32> {\n  return g.light_vp * d.model * vec4<f32>(p, 1.0);\n}\n\n@vertex\nfn vs(@location(0) p: vec3<f32>, @location(1) n: vec3<f32>) -> VsOut {\n  var o: VsOut;\n  let w = d.model * vec4<f32>(p, 1.0);\n  o.w = w.xyz;\n  o.n = (mat3x3<f32>(d.model[0].xyz, d.model[1].xyz, d.model[2].xyz)) * n;\n  o.local = p;\n  o.local_n = n;\n  o.clip = g.proj * g.view * w;\n  return o;\n}\n\nconst PI: f32 = 3.14159265359;\n\nfn d_ggx(noh: f32, a: f32) -> f32 {\n  let a2 = a * a;\n  let den = noh * noh * (a2 - 1.0) + 1.0;\n  return a2 / max(PI * den * den, 1e-7);\n}\n\nfn v_smith(nov: f32, nol: f32, a: f32) -> f32 {\n  let a2 = a * a;\n  let v = nol * sqrt(nov * nov * (1.0 - a2) + a2);\n  let l = nov * sqrt(nol * nol * (1.0 - a2) + a2);\n  return 0.5 / max(v + l, 1e-7);\n}\n\nfn f_schlick(f0: vec3<f32>, u: f32) -> vec3<f32> {\n  let m = clamp(1.0 - u, 0.0, 1.0);\n  let m2 = m * m;\n  return f0 + (vec3<f32>(1.0) - f0) * (m2 * m2 * m);\n}\n\n/**\n * BERX ENVIRONMENT — the analytic room, in WGSL.\n *\n * The same three terms as @berx/spatial's berxEnvironmentRadiance, in\n * the same order, from the same constants: a sky gradient over the\n * upper hemisphere, the floor's weak return below it, and a sun lobe\n * around the key direction. There is no cubemap to sample because BERX\n * ships no captured HDR environment; this is a closed form, which is\n * the only reason four languages can evaluate it identically.\n *\n * `dir` must already be normalised — the caller normalises, and a\n * hidden normalise here would be a place for the ports to differ.\n * `smoothstep(0,1,x)` is WGSL's builtin, which is the same Hermite\n * polynomial berxEnvSmoothstep01 spells out in TypeScript.\n */\nfn berx_environment(dir: vec3<f32>) -> vec3<f32> {\n  let up = clamp(dir.y, 0.0, 1.0);\n  let down = clamp(-dir.y, 0.0, 1.0);\n  let sky = mix(g.env_horizon.rgb, g.env_zenith.rgb, smoothstep(0.0, 1.0, up));\n  // the floor's return is already scaled by `bounce` on the host side\n  let base = mix(sky, g.env_ground.rgb, smoothstep(0.0, 1.0, down));\n  // both vectors point TOWARD the light, so this peaks at 1 looking at it\n  let cos_a = max(dot(dir, g.env_sun_dir.xyz), 0.0);\n  let glow = pow(cos_a, g.env_horizon.w) * g.env_zenith.w;\n  return (base + g.env_sun.rgb * glow) * g.env_ground.w;\n}\n\nfn shade(n: vec3<f32>, v: vec3<f32>, l: vec3<f32>, radiance: vec3<f32>,\n         diffuse_color: vec3<f32>, f0: vec3<f32>, a: f32) -> vec3<f32> {\n  let h = normalize(v + l);\n  let nol = max(dot(n, l), 0.0);\n  if (nol <= 0.0) { return vec3<f32>(0.0); }\n  let nov = max(dot(n, v), 1e-4);\n  let noh = max(dot(n, h), 0.0);\n  let voh = max(dot(v, h), 0.0);\n  let f = f_schlick(f0, voh);\n  let vis = v_smith(nov, nol, a);\n  let dist = d_ggx(noh, a);\n  let spec = f * (dist * vis);\n  // energy that was not reflected is the only energy left to scatter\n  let kd = vec3<f32>(1.0) - f;\n  let diff = kd * diffuse_color / PI;\n  return (diff + spec) * radiance * nol;\n}\n\n/**\n * How much of the key light reaches this point. 1 is full light.\n *\n * The sample is pushed along the surface normal before projecting, which\n * is what stops a lit surface shadowing itself at grazing angles without\n * the constant depth bias that would detach a shadow from the foot of\n * the thing casting it.\n */\nfn key_visibility(world: vec3<f32>, n: vec3<f32>, nol: f32) -> f32 {\n  if (g.shadow.w <= 0.0) { return 1.0; }\n  // more offset where the light grazes, none where it is head-on\n  let slope = clamp(1.0 - nol, 0.0, 1.0);\n  let offset = world + n * (g.shadow.z * (1.0 + slope * 2.0));\n  let light_clip = g.light_vp * vec4<f32>(offset, 1.0);\n  let ndc = light_clip.xyz / max(light_clip.w, 1e-6);\n  // outside the light's own box: lit, not shadowed. A world larger than\n  // the map must not grow a hard black edge where the map ends.\n  if (ndc.x < -1.0 || ndc.x > 1.0 || ndc.y < -1.0 || ndc.y > 1.0 || ndc.z > 1.0) { return 1.0; }\n  let uv = vec2<f32>(ndc.x * 0.5 + 0.5, 0.5 - ndc.y * 0.5);\n  let depth = ndc.z - g.shadow.y;\n  var sum = 0.0;\n  for (var y: i32 = -1; y <= 1; y = y + 1) {\n    for (var x: i32 = -1; x <= 1; x = x + 1) {\n      let tap = uv + vec2<f32>(f32(x), f32(y)) * g.shadow.x;\n      sum = sum + textureSampleCompareLevel(shadow_texture, shadow_sampler, tap, depth);\n    }\n  }\n  let lit = sum / 9.0;\n  return mix(1.0, lit, g.shadow.w);\n}\n\n@fragment\nfn fs(i: VsOut) -> @location(0) vec4<f32> {\n  // Media is a planar projection onto the face that points at you.\n  //\n  // The sample is taken unconditionally and then selected, rather than\n  // taken inside the test: textureSample needs uniform control flow, and\n  // whether a fragment is on the front face and inside the picture is a\n  // per-fragment fact. A backend with nothing to show binds a 1x1\n  // texture and leaves counts.w at zero, so the sample is discarded.\n  let half_extent = vec2<f32>(max(d.base.w, 1e-4), max(d.emissive.w, 1e-4));\n  let uv = (i.local.xy / half_extent) * 0.5 * d.counts.yz + vec2<f32>(0.5);\n  let sampled = textureSample(media_texture, media_sampler, vec2<f32>(uv.x, 1.0 - uv.y)).rgb;\n  let inside = uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0;\n  let facing = normalize(i.local_n).z > 0.5;\n  let base = select(d.base.rgb, sampled, d.counts.w > 0.5 && facing && inside);\n  let n = normalize(i.n);\n  let v = normalize(g.camera.xyz - i.w);\n  let a = max(d.surface.y * d.surface.y, 1e-3);\n  // metals have no diffuse term and tint their reflection; dielectrics\n  // reflect 4% white and keep their colour in the diffuse lobe\n  let diffuse_color = base * (1.0 - d.surface.x);\n  let f0 = mix(vec3<f32>(0.04), base, vec3<f32>(d.surface.x));\n\n  let key_l = normalize(g.key_dir.xyz);\n  // The key alone is shadowed. Ambient and the point lights are not: a\n  // surface out of the sun still receives the room.\n  let visibility = key_visibility(i.w, n, max(dot(n, key_l), 0.0));\n  var lit = shade(n, v, key_l, g.key_col.rgb * g.key_col.w, diffuse_color, f0, a) * visibility;\n\n  let count = i32(d.counts.x);\n  for (var k: i32 = 0; k < 4; k = k + 1) {\n    if (k >= count) { break; }\n    let lp = d.pl_pos[k];\n    let lc = d.pl_col[k];\n    let delta = lp.xyz - i.w;\n    let dist = length(delta);\n    if (dist > lp.w) { continue; }\n    // inverse-square, windowed so a light ends where its range says\n    let win = clamp(1.0 - pow(dist / lp.w, 4.0), 0.0, 1.0);\n    let atten = win * win / max(dist * dist, 1e-4);\n    lit = lit + shade(n, v, delta / max(dist, 1e-4), lc.rgb * lc.w * atten, diffuse_color, f0, a);\n  }\n\n  /* AMBIENT IS NOW THE ROOM, not one colour.\n     Diffuse takes the environment along the normal — what a matte\n     surface actually faces. Specular takes it along the reflection,\n     blended toward the normal by roughness: a rough surface's lobe is\n     wide, so it sees an average of the room rather than a mirror of it,\n     and that blend is this backend's prefilter. There is no prefiltered\n     mip chain because there is no map to prefilter. */\n  let nov = max(dot(n, v), 0.0);\n  let refl = reflect(-v, n);\n  let env_d = berx_environment(n);\n  let env_s = berx_environment(normalize(mix(refl, n, d.surface.y)));\n  let fres = f_schlick(f0, nov);\n  /* AMBIENT OCCLUSION SCALES THE ROOM, AND ONLY THE ROOM.\n     A point in the crease where two surfaces meet can see very little of\n     the environment, which is the darkening the eye reads as contact.\n     The key light already has its own shadow; multiplying a direct light\n     by an ambient term is how a render grows a black core wherever two\n     things touch. g.ssao.x is 1 when the pass ran, 0 when it did not. */\n  let ao = select(1.0, textureLoad(ao_texture, vec2<i32>(i.clip.xy), 0).r, g.ssao.x > 0.5);\n  let amb = (env_d * diffuse_color * (vec3<f32>(1.0) - fres) + env_s * fres) * ao;\n  let colour = lit + amb + d.emissive.rgb;\n  // transmission lets the ground through a glass surface rather than\n  // fading it to nothing\n  let alpha = clamp(d.surface.z * (1.0 - d.surface.w * 0.55), 0.02, 1.0);\n  return vec4<f32>(colour, alpha);\n}\n\n/* ------------------------------------------------------------------ *\n * THE G-BUFFER, for ambient occlusion\n * ------------------------------------------------------------------ *\n *\n * View-space normal in rgb, view-space depth in metres in a. Not a\n * hardware depth texture, and the reason is portability rather than\n * convenience: reconstructing a view position from a depth buffer needs\n * the projection's own conventions, and WGSL's depth range runs 0..1\n * where GL's runs -1..1 — so three backends reconstructing \"the same\"\n * position would be three different reconstructions. A linear view depth\n * written here is the same number everywhere, and the shared core's\n * berxSSAOAt reads exactly these two fields.\n */\n\nstruct GbufOut {\n  @builtin(position) clip: vec4<f32>,\n  @location(0) view_normal: vec3<f32>,\n  @location(1) view_pos: vec3<f32>,\n};\n\n@vertex\nfn vs_gbuffer(@location(0) p: vec3<f32>, @location(1) n: vec3<f32>) -> GbufOut {\n  var o: GbufOut;\n  let w = d.model * vec4<f32>(p, 1.0);\n  let world_n = (mat3x3<f32>(d.model[0].xyz, d.model[1].xyz, d.model[2].xyz)) * n;\n  // into view space: the rotation part of the view matrix\n  o.view_normal = (mat3x3<f32>(g.view[0].xyz, g.view[1].xyz, g.view[2].xyz)) * world_n;\n  o.view_pos = (g.view * w).xyz;\n  o.clip = g.proj * g.view * w;\n  return o;\n}\n\n@fragment\nfn fs_gbuffer(i: GbufOut) -> @location(0) vec4<f32> {\n  // The view looks down -Z, so depth in front of the eye is -view_pos.z.\n  return vec4<f32>(normalize(i.view_normal), -i.view_pos.z);\n}\n";
export const BERX_LABEL_WGSL = "// Names standing in the world, in WGSL. This file is the only copy of it.\n//\n// Unlit on purpose: a name is not a surface in the room, it is a name, and\n// shading it would make it dimmer the further it turned from the key light —\n// the opposite of what a label is for. It is still real geometry, at a real\n// world position with a real height in metres, and depth-tested, so anything\n// in front of it hides it.\n//\n// The quad turns to face the camera by being built from the camera's own\n// right and up vectors, which the shared core hands over with the label's\n// position. Nothing here decides where a name goes.\n\nstruct LabelGlobals {\n  proj: mat4x4<f32>,\n  view: mat4x4<f32>,\n  right: vec4<f32>,\n  up: vec4<f32>,\n};\n\nstruct Label {\n  // xyz world centre, w unused\n  centre: vec4<f32>,\n  // xy half-extent in metres, z alpha, w unused\n  size: vec4<f32>,\n};\n\n@group(0) @binding(0) var<uniform> g: LabelGlobals;\n@group(1) @binding(0) var<uniform> l: Label;\n@group(2) @binding(0) var glyph_sampler: sampler;\n@group(2) @binding(1) var glyph_texture: texture_2d<f32>;\n\nstruct VsOut {\n  @builtin(position) clip: vec4<f32>,\n  @location(0) uv: vec2<f32>,\n};\n\n@vertex\nfn vs(@builtin(vertex_index) v: u32) -> VsOut {\n  // two triangles, as a quad in the camera's plane\n  var corners = array<vec2<f32>, 6>(\n    vec2<f32>(-1.0, -1.0), vec2<f32>(1.0, -1.0), vec2<f32>(1.0, 1.0),\n    vec2<f32>(-1.0, -1.0), vec2<f32>(1.0, 1.0), vec2<f32>(-1.0, 1.0),\n  );\n  let q = corners[v];\n  var o: VsOut;\n  // the rasterised glyphs run top row first, so V is flipped here rather\n  // than in the upload — writeTexture has no flip of its own\n  o.uv = vec2<f32>(q.x * 0.5 + 0.5, 0.5 - q.y * 0.5);\n  let w = l.centre.xyz + g.right.xyz * (q.x * l.size.x) + g.up.xyz * (q.y * l.size.y);\n  o.clip = g.proj * g.view * vec4<f32>(w, 1.0);\n  return o;\n}\n\n@fragment\nfn fs(i: VsOut) -> @location(0) vec4<f32> {\n  let t = textureSample(glyph_texture, glyph_sampler, i.uv);\n  let a = t.a * l.size.z;\n  if (a < 0.01) { discard; }\n  return vec4<f32>(t.rgb, a);\n}\n";
export const BERX_VOLUMETRIC_WGSL = "// BERX volumetric light, in WGSL. This file is the only copy of it.\n//\n// Two backends run this exact text: @berx/spatial-web's WebGPU renderer,\n// which imports it through @berx/spatial-shaders, and the native\n// berx-spatial-native crate, which include_str!s it. WebGL2 runs the same\n// maths as a fullscreen fragment pass (see threeRuntime.ts) — the march\n// below is line for line the same sequence.\n//\n// A fullscreen FRAGMENT pass rather than a compute one, unlike ssao.wgsl,\n// and for a reason: WebGL2 has no compute stage, so a fragment shape is\n// the only one all three backends can run identically. SSAO writes to a\n// storage texture it then reads at a different pixel, which a fragment\n// pass cannot do; this one only ever writes the pixel it is on.\n//\n// What is NOT here is anything that decides the answer: the density, the\n// phase asymmetry, the march length and the intensity all arrive in `v`\n// from @berx/spatial's berxVolumetricUniform, and the loop is the same\n// sequence of operations as that module's berxVolumetricAt — the CPU twin\n// the gate predicts pixels with.\n\nstruct VolGlobals {\n  // the inverse of projection * view, for turning a pixel into a ray\n  inv_view_proj: mat4x4<f32>,\n  // xyz eye position, w unused\n  eye: vec4<f32>,\n  // xyz toward the key light, w unused\n  light_dir: vec4<f32>,\n  // rgb the key's colour, w its intensity\n  light_col: vec4<f32>,\n  // the light's own view-projection, in this API's depth range\n  light_vp: mat4x4<f32>,\n  // x = 1/mapSize, y = depth bias, z unused, w = shadow strength\n  shadow: vec4<f32>,\n  // x = density, y = phase g, z = max distance, w = intensity\n  params: vec4<f32>,\n  // x = march width, y = march height, z = steps, w = march scale\n  //\n  // The march may run at a FRACTION of the frame: a shaft is a smooth,\n  // low-frequency thing with no edges of its own — only the ones the\n  // shadow map gives it — so it survives being computed at half\n  // resolution and upsampled, and the cost is quadratic in that choice.\n  // xy are therefore the MARCH's dimensions, and w says how many frame\n  // pixels one of them covers, which is all the G-buffer fetch needs.\n  dims: vec4<f32>,\n  // xyz the camera's forward direction, w unused. Turns the G-buffer's\n  // view depth into a distance along THIS ray.\n  forward: vec4<f32>,\n};\n\n@group(0) @binding(0) var<uniform> v: VolGlobals;\n@group(0) @binding(1) var shadow_sampler: sampler_comparison;\n@group(0) @binding(2) var shadow_texture: texture_depth_2d;\n// rgb = view-space normal, a = linear view depth in metres (0 = nothing)\n@group(0) @binding(3) var gbuffer: texture_2d<f32>;\n\n// The composite's own resources, on a second group: a WGSL module cannot\n// declare two different resources at the same @group/@binding, and the\n// composite reads what the march wrote rather than what the march read.\n@group(1) @binding(0) var vol_sampler: sampler;\n@group(1) @binding(1) var vol_texture: texture_2d<f32>;\n\nconst PI: f32 = 3.14159265359;\n\nstruct VsOut {\n  @builtin(position) clip: vec4<f32>,\n  @location(0) uv: vec2<f32>,\n};\n\n@vertex\nfn vs_fullscreen(@builtin(vertex_index) i: u32) -> VsOut {\n  // one triangle covering the screen: fewer vertices than a quad and no\n  // seam down the diagonal where two triangles meet\n  var corners = array<vec2<f32>, 3>(\n    vec2<f32>(-1.0, -1.0), vec2<f32>(3.0, -1.0), vec2<f32>(-1.0, 3.0),\n  );\n  let c = corners[i];\n  var o: VsOut;\n  o.clip = vec4<f32>(c, 0.0, 1.0);\n  o.uv = vec2<f32>(c.x * 0.5 + 0.5, 0.5 - c.y * 0.5);\n  return o;\n}\n\n/**\n * Henyey–Greenstein. The same curve as @berx/spatial's berxPhaseHG,\n * including the clamp: at g→1 and cosTheta→1 the denominator goes to\n * zero and the phase to infinity, which is the singular lobe that blows\n * a shaft out to white.\n */\nfn phase_hg(cos_theta: f32, g: f32) -> f32 {\n  let g2 = g * g;\n  let denom = 1.0 + g2 - 2.0 * g * cos_theta;\n  return (1.0 - g2) / (4.0 * PI * pow(max(denom, 1e-4), 1.5));\n}\n\n/**\n * FNV-1a over the pixel coordinate — the same hash as\n * berxVolumetricJitter, which is why a shaft dithers identically in\n * four languages without shipping a noise texture.\n */\nfn jitter(x: i32, y: i32) -> f32 {\n  var h: u32 = 0x811c9dc5u;\n  h = h ^ (u32(x) & 0xffffu);\n  h = h * 0x01000193u;\n  h = h ^ (u32(y) & 0xffffu);\n  h = h * 0x01000193u;\n  return f32(h >> 8u) / 16777216.0;\n}\n\n/** 1 where the key light reaches this point, 0 where the map says it does not. */\nfn lit_at(world: vec3<f32>) -> f32 {\n  if (v.shadow.w <= 0.0) { return 1.0; }\n  let clip = v.light_vp * vec4<f32>(world, 1.0);\n  let ndc = clip.xyz / max(clip.w, 1e-6);\n  // outside the light's own box the air is lit, not dark: a world larger\n  // than the map must not grow a hard black wall where the map ends\n  if (ndc.x < -1.0 || ndc.x > 1.0 || ndc.y < -1.0 || ndc.y > 1.0 || ndc.z > 1.0) { return 1.0; }\n  let uv = vec2<f32>(ndc.x * 0.5 + 0.5, 0.5 - ndc.y * 0.5);\n  return textureSampleCompareLevel(shadow_texture, shadow_sampler, uv, ndc.z - v.shadow.y);\n}\n\n@fragment\nfn fs_volumetric(i: VsOut) -> @location(0) vec4<f32> {\n  let px = i32(i.uv.x * v.dims.x);\n  let py = i32(i.uv.y * v.dims.y);\n\n  // The ray through this pixel, from the inverse view-projection. Two\n  // points on it rather than a direction guess, so the reconstruction is\n  // exactly the camera's own.\n  let ndc = vec2<f32>(i.uv.x * 2.0 - 1.0, 1.0 - i.uv.y * 2.0);\n  let near_h = v.inv_view_proj * vec4<f32>(ndc, 0.0, 1.0);\n  let far_h = v.inv_view_proj * vec4<f32>(ndc, 1.0, 1.0);\n  let near_p = near_h.xyz / max(near_h.w, 1e-6);\n  let far_p = far_h.xyz / max(far_h.w, 1e-6);\n  let dir = normalize(far_p - near_p);\n\n  // Distance to the first surface. The march stops there: air behind a\n  // wall does not scatter light into the eye, and marching past it is how\n  // a volumetric pass glows through solid objects.\n  //\n  // The G-buffer stores VIEW DEPTH — distance along the camera's forward\n  // axis — and the march needs distance along THIS ray. For an off-axis\n  // pixel those differ by 1/cos, and using the depth directly cuts the\n  // march short by that factor: a measurable error toward the corners of\n  // the frame, and one the CPU twin would reproduce only by making the\n  // same mistake.\n  // The G-buffer is always at FRAME resolution — the occlusion pass reads\n  // it per pixel and cannot be cheapened the same way — so a march pixel\n  // maps to the centre of the block it covers. At scale 1 this is exactly\n  // (px, py), which is why turning the scale on changes nothing at HIGH.\n  let scale = max(v.dims.w, 1.0);\n  let gxy = vec2<f32>(f32(px), f32(py)) * scale + vec2<f32>((scale - 1.0) * 0.5);\n  let g = textureLoad(gbuffer, vec2<i32>(gxy), 0);\n  let along = max(dot(dir, normalize(v.forward.xyz)), 1e-3);\n  let surface = select(v.params.z, g.a / along, g.a > 0.0);\n  let far = min(v.params.z, surface);\n  if (far <= 0.0) { return vec4<f32>(0.0, 0.0, 0.0, 1.0); }\n\n  let steps = i32(v.dims.z);\n  let step_length = far / f32(steps);\n  let phase = phase_hg(dot(dir, normalize(v.light_dir.xyz)), v.params.y);\n  let offset = jitter(px, py);\n\n  var inscatter = 0.0;\n  for (var s: i32 = 0; s < steps; s = s + 1) {\n    let t = (f32(s) + offset) * step_length;\n    let p = v.eye.xyz + dir * t;\n    let lit = lit_at(p);\n    if (lit <= 0.0) { continue; }\n    // Beer–Lambert: what scatters here still has to reach the eye\n    let transmittance = exp(-v.params.x * t);\n    inscatter = inscatter + lit * phase * v.params.x * step_length * transmittance;\n  }\n\n  let energy = inscatter * v.params.w;\n  // The scattering is grey; the colour is the key light's own. Keeping\n  // them apart means a change of light colour cannot silently change the\n  // amount of scattering.\n  return vec4<f32>(v.light_col.rgb * v.light_col.w * energy, 1.0);\n}\n\n/**\n * The additive composite.\n *\n * Light in the air ADDS to what is behind it. A composite that blended\n * over the world would be a fog overlay: it would darken something, and\n * scattering never darkens anything. The blend state on the pipeline is\n * ONE/ONE for exactly that reason, and this shader only has to hand back\n * the in-scatter it was given.\n */\n@fragment\nfn fs_composite(i: VsOut) -> @location(0) vec4<f32> {\n  /**\n   * A bilinear tap, written out rather than asked of a sampler.\n   *\n   * The march target is rgba32float, and a 32-bit float texture is not\n   * filterable in WebGPU without an optional feature no phone is\n   * guaranteed to have. Dropping to rgba16float would have bought\n   * hardware filtering — and would have moved the volumetric gate's\n   * oracle tolerance from 1e-7 to about 1e-3 to accommodate it, which is\n   * loosening a measurement to fit a change rather than the other way\n   * round. Four loads and three mixes cost less than that.\n   *\n   * At scale 1 the sample lands exactly on a texel centre, f is zero in\n   * both axes, and this returns the same value a nearest tap did — so\n   * the full-resolution picture is unchanged, bit for bit.\n   */\n  let size = vec2<f32>(textureDimensions(vol_texture));\n  let p = i.uv * size - vec2<f32>(0.5);\n  let base = floor(p);\n  let f = p - base;\n  let hi = size - vec2<f32>(1.0);\n  let c00 = vec2<i32>(clamp(base, vec2<f32>(0.0), hi));\n  let c10 = vec2<i32>(clamp(base + vec2<f32>(1.0, 0.0), vec2<f32>(0.0), hi));\n  let c01 = vec2<i32>(clamp(base + vec2<f32>(0.0, 1.0), vec2<f32>(0.0), hi));\n  let c11 = vec2<i32>(clamp(base + vec2<f32>(1.0, 1.0), vec2<f32>(0.0), hi));\n  let top = mix(textureLoad(vol_texture, c00, 0).rgb, textureLoad(vol_texture, c10, 0).rgb, f.x);\n  let bottom = mix(textureLoad(vol_texture, c01, 0).rgb, textureLoad(vol_texture, c11, 0).rgb, f.x);\n  return vec4<f32>(mix(top, bottom, f.y), 1.0);\n}\n";
export const BERX_SSAO_WGSL = "// BERX SSAO, in WGSL. This file is the only copy of it.\n//\n// Two backends run this exact text: @berx/spatial-web's WebGPU renderer,\n// which imports it through @berx/spatial-shaders, and the native\n// berx-spatial-native crate, which include_str!s it. WebGL2 has no\n// compute stage, so it runs the same maths as a fullscreen fragment pass\n// (see threeRuntime.ts) — the loop is line for line this one.\n//\n// It is a separate module from world.wgsl rather than another entry point\n// in it because a WGSL module cannot declare two different resources at\n// the same @group/@binding, and this pass needs its own bind group.\n\n/* ------------------------------------------------------------------ *\n * SSAO — the compute pass\n * ------------------------------------------------------------------ *\n *\n * The loop is here because a pixel has to ask its neighbours, and that\n * cannot be a closed form. What is NOT here is anything that decides the\n * answer: the sample kernel, the radius, the bias, the strength and the\n * falloff all arrive in `k` from @berx/spatial's berxSSAOUniform, and the\n * accumulation below is the same sequence of operations as that module's\n * berxSSAOAt — which is the CPU twin the gate predicts pixels with.\n *\n * There is no per-pixel random rotation and no blur pass to hide one.\n * The kernel is an evenly-spaced golden-angle spiral, which does not need\n * the rotation, and a blur would add a radius three backends would have\n * to agree on for no gain.\n */\n\nstruct SsaoKernel {\n  // BERX_SSAO_SAMPLES hemisphere offsets, then one vec4 of parameters:\n  // x = radius, y = bias, z = strength, w = power.\n  s: array<vec4<f32>, 17>,\n};\n\n@group(0) @binding(0) var<uniform> sk: SsaoKernel;\n@group(0) @binding(1) var gbuffer: texture_2d<f32>;\n@group(0) @binding(2) var ao_out: texture_storage_2d<r32float, write>;\n// x = width, y = height, z = focal length in pixels, w unused\n// x = width, y = height, z = focal length in pixels, w = LIVE TAPS\n//\n// The kernel buffer is always sixteen vec4s so that a change of quality\n// cannot change its size — and therefore cannot invalidate a bind group\n// naming it. A tier that can only afford eight gets a STRIDE through the\n// spiral in the first eight slots, zeroes in the rest, and this count.\n@group(0) @binding(3) var<uniform> sdim: vec4<f32>;\n\n@compute @workgroup_size(8, 8)\nfn cs_ssao(@builtin(global_invocation_id) id: vec3<u32>) {\n  let w = i32(sdim.x);\n  let h = i32(sdim.y);\n  let x = i32(id.x);\n  let y = i32(id.y);\n  if (x >= w || y >= h) { return; }\n\n  let centre = textureLoad(gbuffer, vec2<i32>(x, y), 0);\n  // nothing was drawn here, so there is nothing to occlude\n  if (centre.a <= 0.0) {\n    textureStore(ao_out, vec2<i32>(x, y), vec4<f32>(1.0, 0.0, 0.0, 1.0));\n    return;\n  }\n\n  let params = sk.s[16];\n  let radius = params.x;\n  let strength = params.z;\n  let power = params.w;\n  let n = normalize(centre.xyz);\n\n  // A deterministic basis, not a noise-texture rotation — see the note\n  // above and berxSSAOAt's own.\n  var up = vec3<f32>(0.0, 0.0, 1.0);\n  if (abs(n.z) >= 0.999) { up = vec3<f32>(1.0, 0.0, 0.0); }\n  let tx = normalize(cross(up, n));\n  let ty = cross(n, tx);\n  // Slope-scaled bias — see berxSSAOAt's own note. A sample lands on a\n  // whole pixel, and on an oblique surface the geometry there is up to\n  // half a pixel of slope away in depth; a constant bias leaves every\n  // tilted surface with a uniform haze.\n  let slope = 1.0 - min(1.0, abs(n.z));\n  let bias = params.y * (1.0 + slope * 4.0);\n\n  var occluded = 0.0;\n  let taps = i32(sdim.w);\n  for (var j: i32 = 0; j < 16; j = j + 1) {\n    if (j >= taps) { break; }\n    let k = sk.s[j].xyz;\n    let s = tx * k.x + ty * k.y + n * k.z;\n    let sample_depth = centre.a - s.z * radius;\n    if (sample_depth <= 0.0) { continue; }\n    let sx = x + i32(round((s.x * radius * sdim.z) / sample_depth));\n    let sy = y - i32(round((s.y * radius * sdim.z) / sample_depth));\n    if (sx < 0 || sy < 0 || sx >= w || sy >= h) { continue; }\n    let there = textureLoad(gbuffer, vec2<i32>(sx, sy), 0);\n    if (there.a <= 0.0) { continue; }\n    if (there.a < sample_depth - bias) {\n      // range check: without it every silhouette grows a dark halo from\n      // whatever happens to be far behind it\n      let range = radius / max(abs(centre.a - there.a), 1e-4);\n      occluded = occluded + min(1.0, range);\n    }\n  }\n\n  let ratio = occluded / f32(max(taps, 1));\n  let ao = max(0.0, 1.0 - pow(ratio, power) * strength);\n  textureStore(ao_out, vec2<i32>(x, y), vec4<f32>(ao, 0.0, 0.0, 1.0));\n}\n";
export const BERX_PARTICLES_WGSL = "// BERX particles, in WGSL. This file is the only copy of it.\n//\n// Two backends run this exact text: @berx/spatial-web's WebGPU renderer,\n// which imports it through @berx/spatial-shaders, and the native\n// berx-spatial-native crate, which include_str!s it. WebGL2 runs the same\n// maths as a GLSL port (see threeRuntime.ts) — the hash and the placement\n// below are the same sequence.\n//\n// NOTHING IS READ FROM A BUFFER. Each vertex works out where its own\n// particle is from a hash of its index, exactly as @berx/spatial's\n// berxParticleAt does — which is what makes the field identical in four\n// languages without a buffer to keep in sync, and what lets a CPU twin\n// say where every particle will be before the GPU draws it.\n//\n// Six vertices per particle, expanded from the vertex index alone: a\n// camera-facing quad needs no vertex buffer at all when its corners come\n// from arithmetic.\n\nstruct ParticleGlobals {\n  proj: mat4x4<f32>,\n  view: mat4x4<f32>,\n  // xyz what the field is arranged around, w the time in seconds\n  origin: vec4<f32>,\n  // rgb colour, a peak alpha\n  colour: vec4<f32>,\n  // x = extent, y = speed, z = size, w = period\n  shape: vec4<f32>,\n  // x = count, y = kind (0 dust, 1 energy, 2 stars), zw unused\n  counts: vec4<f32>,\n  // the camera's right and up, for the quads that face it\n  right: vec4<f32>,\n  up: vec4<f32>,\n};\n\n@group(0) @binding(0) var<uniform> p: ParticleGlobals;\n\nconst PI: f32 = 3.14159265359;\n\n/**\n * FNV-1a over an index and a lane — the same hash as\n * berxParticleHash. `lane` turns one index into several independent\n * numbers without needing four hashes or a table.\n */\nfn phash(index: u32, lane: u32) -> f32 {\n  var h: u32 = 0x811c9dc5u;\n  h = h ^ (index & 0xffffu);\n  h = h * 0x01000193u;\n  h = h ^ ((index >> 16u) & 0xffffu);\n  h = h * 0x01000193u;\n  h = h ^ (lane & 0xffffu);\n  h = h * 0x01000193u;\n  return f32(h >> 8u) / 16777216.0;\n}\n\nstruct Particle {\n  centre: vec3<f32>,\n  alpha: f32,\n  size: f32,\n};\n\n/** The same placement as berxParticleAt, term for term. */\nfn particle_at(index: u32) -> Particle {\n  let hx = phash(index, 1u);\n  let hy = phash(index, 2u);\n  let hz = phash(index, 3u);\n  let hp = phash(index, 4u);\n  let extent = p.shape.x;\n  let speed = p.shape.y;\n  let size = p.shape.z;\n  let period = p.shape.w;\n  let alpha = p.colour.a;\n  let phase = fract(p.origin.w / period + hp);\n\n  var out: Particle;\n  if (p.counts.y > 0.5 && p.counts.y < 1.5) {\n    // energy: a spiral leaving a surface, not a column of dots\n    let angle = hx * PI * 2.0 + phase * PI * 4.0;\n    let radius = extent * (0.25 + hy * 0.55) * (1.0 - phase * 0.45);\n    out.centre = vec3<f32>(\n      p.origin.x + cos(angle) * radius,\n      p.origin.y - extent * 0.4 + phase * extent * 1.8,\n      p.origin.z + sin(angle) * radius,\n    );\n    // fades in and out over its own life: a particle that appears at\n    // full brightness is a flicker, not a rising ember\n    out.alpha = alpha * sin(phase * PI);\n    out.size = size * (0.6 + hz * 0.8);\n    return out;\n  }\n\n  // dust and stars: a hashed cube around the origin, drifting. The drift\n  // wraps by construction, so there is no respawn and no lifetime\n  // bookkeeping to desynchronise between backends.\n  var drift = phase * extent;\n  if (speed == 0.0) { drift = 0.0; }\n  let wx = fract((hx * extent + drift * 0.35) / extent) * extent - extent * 0.5;\n  let wy = fract((hy * extent + drift) / extent) * extent - extent * 0.5;\n  let wz = fract((hz * extent + drift * 0.2) / extent) * extent - extent * 0.5;\n  out.centre = vec3<f32>(p.origin.x + wx, p.origin.y + wy, p.origin.z + wz);\n  // stars twinkle very slightly; dust does not — a twinkling mote in the\n  // near field reads as a rendering error\n  if (p.counts.y > 1.5) {\n    out.alpha = alpha * (0.65 + 0.35 * sin(phase * PI * 2.0));\n  } else {\n    out.alpha = alpha;\n  }\n  out.size = size * (0.7 + hz * 0.6);\n  return out;\n}\n\nstruct VsOut {\n  @builtin(position) clip: vec4<f32>,\n  @location(0) uv: vec2<f32>,\n  @location(1) alpha: f32,\n};\n\n@vertex\nfn vs_particles(@builtin(vertex_index) v: u32) -> VsOut {\n  let index = v / 6u;\n  let corner = v % 6u;\n  var corners = array<vec2<f32>, 6>(\n    vec2<f32>(-1.0, -1.0), vec2<f32>(1.0, -1.0), vec2<f32>(1.0, 1.0),\n    vec2<f32>(-1.0, -1.0), vec2<f32>(1.0, 1.0), vec2<f32>(-1.0, 1.0),\n  );\n  let q = corners[corner];\n  let particle = particle_at(index);\n  let world = particle.centre\n    + p.right.xyz * (q.x * particle.size)\n    + p.up.xyz * (q.y * particle.size);\n  var o: VsOut;\n  o.uv = q;\n  o.alpha = particle.alpha;\n  o.clip = p.proj * p.view * vec4<f32>(world, 1.0);\n  return o;\n}\n\n@fragment\nfn fs_particles(i: VsOut) -> @location(0) vec4<f32> {\n  // A round, soft mote. A square particle reads as a missing texture,\n  // and a hard-edged circle reads as a UI dot.\n  let r = length(i.uv);\n  if (r > 1.0) { discard; }\n  let falloff = 1.0 - r * r;\n  let a = i.alpha * falloff * falloff;\n  if (a < 0.002) { discard; }\n  // premultiplied: these are drawn additively, so the colour carries the\n  // alpha and the blend adds it to whatever is behind\n  return vec4<f32>(p.colour.rgb * a, a);\n}\n";
export const BERX_POST_WGSL = "// BERX post, in WGSL. This file is the only copy of it.\n//\n// Two backends run this exact text: @berx/spatial-web's WebGPU renderer,\n// which imports it through @berx/spatial-shaders, and the native\n// berx-spatial-native crate, which include_str!s it. WebGL2 runs the same\n// maths as a fullscreen fragment pass (see threeRuntime.ts) — the five\n// constants below are the same five numbers there and in Rust and in\n// @berx/spatial's berxExposure, which is the CPU twin the gate predicts\n// pixels with.\n//\n// This stage was declared `absent` in renderPipeline.ts for the whole of\n// the project's life, and the honesty of that label is what made the\n// problem findable: there was no tone-map, so the frame was whatever the\n// world pass wrote, and what the world pass wrote was every brand colour\n// dimmed by the room's own light transport. #15191E on #07080A came out\n// 7 against 7 out of 255 — an object and a void the same colour to\n// within half a code value.\n//\n// WHAT RUNS HERE, in order, and the order is the whole point:\n//\n//   linear HDR  ->  x exposure  ->  shoulder  ->  8-bit frame\n//\n// The input is the frame AFTER the air has been added, because\n// in-scatter is light and light is part of what is being exposed.\n// Tone-mapping the surfaces and then adding the air would put unmapped\n// values on top of mapped ones, which is not a brighter picture — it is\n// two different pictures added together.\n\nstruct PostGlobals {\n  // x = exposure gain, y..w unused\n  params: vec4<f32>,\n};\n\n@group(0) @binding(0) var frame_texture: texture_2d<f32>;\n@group(0) @binding(1) var<uniform> p: PostGlobals;\n\nstruct VsOut {\n  @builtin(position) clip: vec4<f32>,\n  @location(0) uv: vec2<f32>,\n};\n\n@vertex\nfn vs_post(@builtin(vertex_index) i: u32) -> VsOut {\n  // one triangle covering the screen: fewer vertices than a quad and no\n  // seam down the diagonal where two triangles meet\n  var corners = array<vec2<f32>, 3>(\n    vec2<f32>(-1.0, -1.0), vec2<f32>(3.0, -1.0), vec2<f32>(-1.0, 3.0),\n  );\n  let c = corners[i];\n  var o: VsOut;\n  o.clip = vec4<f32>(c, 0.0, 1.0);\n  o.uv = vec2<f32>(c.x * 0.5 + 0.5, 0.5 - c.y * 0.5);\n  return o;\n}\n\n// The ACES filmic fit (Narkowicz). Five constants, four languages, one\n// set of numbers.\n//\n// Chosen over a Reinhard curve for what it does to HUE, which is the\n// thing a brand palette cannot afford to lose: past white it desaturates\n// toward white the way film does, instead of clipping each channel on\n// its own and turning a bright teal into a cyan and then into a flat\n// white. It also lifts the middle — f(0.18) = 0.267 — which is why the\n// gain does not have to be larger than the measured transport says.\nfn shoulder(x: f32) -> f32 {\n  let v = max(x, 0.0);\n  let mapped = (v * (2.51 * v + 0.03)) / (v * (2.43 * v + 0.59) + 0.14);\n  return clamp(mapped, 0.0, 1.0);\n}\n\n@fragment\nfn fs_post(i: VsOut) -> @location(0) vec4<f32> {\n  // A LOAD, not a sample. This pass is one output pixel per input\n  // pixel, so there is nothing to filter and a bilinear tap only\n  // introduces a half-texel question each API answers its own way — it\n  // was worth exactly three disagreeing pixels along the top edge\n  // between the two web backends. An integer fetch has no such\n  // question and makes them identical by construction.\n  let hdr = textureLoad(frame_texture, vec2<i32>(i.clip.xy), 0);\n  let e = hdr.rgb * p.params.x;\n  // Per channel, and the shoulder is what keeps that from being three\n  // independent clips: two colours that both pass 1.0 stay different\n  // numbers on screen instead of both being white.\n  return vec4<f32>(shoulder(e.r), shoulder(e.g), shoulder(e.b), 1.0);\n}\n";
